package com.mealmate.availability.service;
import com.mealmate.availability.domain.*; import com.mealmate.availability.repository.*; import com.mealmate.availability.web.AvailabilityDtos.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class AvailabilityService { private final AvailabilityRepository availability; private final ReservationRepository reservations; public AvailabilityService(AvailabilityRepository a,ReservationRepository r){availability=a;reservations=r;}
 @Transactional(readOnly=true) public AvailabilityResponse get(UUID id){Availability a=availability.findByMenuItemId(id).orElseThrow(()->new NoSuchElementException("Availability not found: "+id));return new AvailabilityResponse(id,a.getQuantity(),a.getReservedQuantity(),a.available());}
 public AvailabilityResponse set(UUID menuItemId, AvailabilityRequest x){Availability a=availability.findByMenuItemId(menuItemId).orElseGet(()->new Availability(menuItemId,0));a.setQuantity(x.quantity());availability.save(a);return new AvailabilityResponse(menuItemId,a.getQuantity(),a.getReservedQuantity(),a.available());}
 public ReservationResponse reserve(ReservationRequest x){if(reservations.existsByOrderId(x.orderId())){return response(x.orderId(),reservations.findByOrderId(x.orderId()));} Map<UUID,Integer> requested=new LinkedHashMap<>(); for(QuantityRequest line:x.items())requested.merge(line.menuItemId(),line.quantity(),Integer::sum); List<Availability> rows=new ArrayList<>(); for(var e:requested.entrySet()){Availability a=availability.findLockedByMenuItemId(e.getKey()).orElseThrow(()->new IllegalStateException("No availability for menu item: "+e.getKey())); if(a.available()<e.getValue())throw new InsufficientAvailabilityException(e.getKey());rows.add(a);} int i=0; List<QuantityRequest> result=new ArrayList<>(); for(var e:requested.entrySet()){rows.get(i++).reserve(e.getValue());reservations.save(new Reservation(x.orderId(),e.getKey(),e.getValue()));result.add(new QuantityRequest(e.getKey(),e.getValue()));}return new ReservationResponse(x.orderId(),result);}
 public void release(UUID orderId){for(Reservation r:reservations.findByOrderId(orderId)){Availability a=availability.findByMenuItemId(r.getMenuItemId()).orElseThrow(()->new IllegalStateException("Availability missing: "+r.getMenuItemId()));a.release(r.getQuantity());reservations.delete(r);}}
 private ReservationResponse response(UUID id,List<Reservation> rs){return new ReservationResponse(id,rs.stream().map(r->new QuantityRequest(r.getMenuItemId(),r.getQuantity())).toList());} public static class InsufficientAvailabilityException extends RuntimeException{public InsufficientAvailabilityException(UUID id){super("Insufficient availability for menu item: "+id);}}
}
